PASSPORT_REFRESH_GUARD = r"""
CREATE FUNCTION credential_passport_refresh_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  source_student uuid;
  source_time timestamptz;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'passport refresh requests cannot be deleted' USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.source_type = 'CREDENTIAL_LIFECYCLE' THEN
      SELECT c.student_id, e.occurred_at INTO source_student, source_time
        FROM credential_lifecycle_events e
        JOIN credentials c ON c.id = e.credential_id
       WHERE e.id = NEW.lifecycle_event_id;
      IF NOT FOUND OR source_student <> NEW.student_id
         OR source_time <> NEW.source_occurred_at
         OR NEW.event_key <> 'credential-lifecycle:' || NEW.lifecycle_event_id::text THEN
        RAISE EXCEPTION 'passport refresh does not match its lifecycle event' USING ERRCODE = '23514';
      END IF;
    ELSIF NEW.source_type = 'EXPIRATION' THEN
      IF NEW.lifecycle_event_id IS NOT NULL
         OR NEW.event_key !~ ('^credential-expiration:' || NEW.student_id::text || ':[0-9]+$') THEN
        RAISE EXCEPTION 'invalid credential expiration refresh identity' USING ERRCODE = '23514';
      END IF;
    ELSE
      RAISE EXCEPTION 'unsupported passport refresh source' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.event_key IS DISTINCT FROM OLD.event_key
     OR NEW.source_type IS DISTINCT FROM OLD.source_type
     OR NEW.student_id IS DISTINCT FROM OLD.student_id
     OR NEW.lifecycle_event_id IS DISTINCT FROM OLD.lifecycle_event_id
     OR NEW.source_occurred_at IS DISTINCT FROM OLD.source_occurred_at
     OR NEW.max_attempts IS DISTINCT FROM OLD.max_attempts
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'passport refresh source identity is immutable' USING ERRCODE = '23514';
  END IF;

  IF OLD.status = 'COMPLETED' THEN
    RAISE EXCEPTION 'completed passport refresh requests are immutable' USING ERRCODE = '23514';
  ELSIF OLD.status = 'FAILED' THEN
    IF NEW.status <> 'PENDING' OR NEW.attempt_count <> 0
       OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL
       OR NEW.completed_at IS NOT NULL THEN
      RAISE EXCEPTION 'failed passport refresh may only be explicitly requeued' USING ERRCODE = '23514';
    END IF;
  ELSIF OLD.status = 'PENDING' THEN
    IF NEW.status <> 'PROCESSING' OR NEW.attempt_count <> OLD.attempt_count + 1
       OR NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL THEN
      RAISE EXCEPTION 'invalid pending passport refresh claim' USING ERRCODE = '23514';
    END IF;
  ELSIF OLD.status = 'PROCESSING' AND NEW.status = 'PROCESSING' THEN
    IF OLD.lease_expires_at > clock_timestamp()
       OR NEW.attempt_count <> OLD.attempt_count + 1
       OR NEW.lease_token IS NULL OR NEW.lease_token = OLD.lease_token
       OR NEW.lease_expires_at IS NULL THEN
      RAISE EXCEPTION 'processing passport refresh lease is not stale' USING ERRCODE = '23514';
    END IF;
  ELSIF OLD.status = 'PROCESSING' AND NEW.status IN ('PENDING', 'COMPLETED', 'FAILED') THEN
    IF NEW.attempt_count <> OLD.attempt_count
       OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL THEN
      RAISE EXCEPTION 'invalid passport refresh completion transition' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'FAILED' AND NEW.attempt_count <> NEW.max_attempts THEN
      RAISE EXCEPTION 'passport refresh may fail terminally only at its retry limit' USING ERRCODE = '23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'invalid passport refresh status transition' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER credential_passport_refresh_guard_trg
BEFORE INSERT OR UPDATE OR DELETE ON credential_passport_refreshes
FOR EACH ROW EXECUTE FUNCTION credential_passport_refresh_guard();
"""

ISSUER_PROVISIONING_GUARDS = r"""
CREATE FUNCTION credential_issuer_provisioning_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE actor_id text; actor_email text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_trusted THEN
      RAISE EXCEPTION 'trusted BTU credential issuer cannot be deleted' USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;

  actor_id := current_setting('app.credential_issuer_actor_id', true);
  actor_email := current_setting('app.credential_issuer_actor_email', true);
  IF TG_OP = 'INSERT' THEN
    IF NEW.is_trusted THEN
      IF NEW.reference <> 'BTU-UNIVERSITY' OR COALESCE(actor_id, '') = ''
         OR COALESCE(actor_email, '') = '' THEN
        RAISE EXCEPTION 'trusted BTU issuer requires authorized provisioning context' USING ERRCODE = '23514';
      END IF;
      PERFORM actor_id::uuid;
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.is_trusted AND (NEW.reference <> OLD.reference OR NOT NEW.is_trusted) THEN
    RAISE EXCEPTION 'trusted BTU issuer identity cannot be changed or removed' USING ERRCODE = '23514';
  END IF;
  IF NEW.is_trusted AND NOT OLD.is_trusted AND NEW.reference <> 'BTU-UNIVERSITY' THEN
    RAISE EXCEPTION 'only the fixed BTU issuer may be trusted' USING ERRCODE = '23514';
  END IF;
  IF NEW.is_trusted AND NOT OLD.is_trusted OR
     (OLD.is_trusted AND NEW.display_name IS DISTINCT FROM OLD.display_name) THEN
    IF COALESCE(actor_id, '') = '' OR COALESCE(actor_email, '') = '' THEN
      RAISE EXCEPTION 'issuer trust or display changes require provisioning context' USING ERRCODE = '23514';
    END IF;
    PERFORM actor_id::uuid;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION credential_issuer_provisioning_audit() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE actor_id text; actor_email text;
BEGIN
  actor_id := current_setting('app.credential_issuer_actor_id', true);
  actor_email := current_setting('app.credential_issuer_actor_email', true);
  IF TG_OP = 'INSERT' AND NEW.is_trusted THEN
    INSERT INTO credential_issuer_provisioning_events
      (id, issuer_id, actor_user_id, actor_email, event_type, previous_display_name, display_name, occurred_at)
    VALUES
      (gen_random_uuid(), NEW.id, actor_id, actor_email, 'PROVISIONED', '', NEW.display_name, clock_timestamp());
  ELSIF TG_OP = 'UPDATE' AND NEW.is_trusted AND NOT OLD.is_trusted THEN
    INSERT INTO credential_issuer_provisioning_events
      (id, issuer_id, actor_user_id, actor_email, event_type, previous_display_name, display_name, occurred_at)
    VALUES
      (gen_random_uuid(), NEW.id, actor_id, actor_email, 'PROVISIONED', '', NEW.display_name, clock_timestamp());
  ELSIF TG_OP = 'UPDATE' AND OLD.is_trusted AND
        NEW.display_name IS DISTINCT FROM OLD.display_name THEN
    INSERT INTO credential_issuer_provisioning_events
      (id, issuer_id, actor_user_id, actor_email, event_type, previous_display_name, display_name, occurred_at)
    VALUES
      (gen_random_uuid(), NEW.id, actor_id, actor_email, 'DISPLAY_NAME_CHANGED', OLD.display_name, NEW.display_name, clock_timestamp());
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER credential_issuer_provisioning_guard_trg
BEFORE INSERT OR UPDATE OR DELETE ON credential_issuers
FOR EACH ROW EXECUTE FUNCTION credential_issuer_provisioning_guard();
CREATE TRIGGER credential_issuer_provisioning_audit_trg
AFTER INSERT OR UPDATE ON credential_issuers
FOR EACH ROW EXECUTE FUNCTION credential_issuer_provisioning_audit();

CREATE FUNCTION credential_issuer_audit_immutable() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP <> 'INSERT' OR pg_trigger_depth() < 2 THEN
    RAISE EXCEPTION 'issuer provisioning audit rows are append-only and trigger-created' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER credential_issuer_audit_immutable_trg
BEFORE INSERT OR UPDATE OR DELETE ON credential_issuer_provisioning_events
FOR EACH ROW EXECUTE FUNCTION credential_issuer_audit_immutable();
"""

